// sfnx's stdin (tools/sfnx.cpp): the control lines that act at once and the queue of the rest, with the request numbers
// that tie each flag to the request it is for. Plain C++ (tools/sfnx_input_test.cpp tests it without a GPU)
#pragma once

#include <atomic>
#include <chrono>
#include <condition_variable>
#include <cstdio>
#include <deque>
#include <iostream>
#include <mutex>
#include <string>
#include <utility>

namespace sfnx {

constexpr int MAX_SLOTS = 8;

// stdin: STOP, BSTOP <slot> and BYIELD <slot> act the moment they arrive; every other line is queued with its number
// (request lines are counted in arrival order). A flag holds the number of the latest request it is for, so nothing ever
// clears it and one sent before a request's line never acts on that request, while one sent after does however long
// the request waits in the queue: STOP is for the latest request line in and no other (the front end sends a request's
// line and its STOP under one control lock, so the latest line is the request it means; an older one still queued is
// another client's), BSTOP <slot> and BYIELD <slot> for that slot's latest BGEN / BGENI, and BYIELD also for the latest
// GEN / GENI (a solo read gives way, its part read waiting in the slot named)
struct Input {
    std::mutex mu;
    std::condition_variable cv;
    std::deque<std::pair<std::string, long>> lines;
    bool eof = false;
    long seq = 0;       // request lines queued (under mu)
    long running = 0;   // the request the engine is on (begin / end; under mu), 0: none
    // the reader's own: the numbers of the latest GEN / GENI and of each slot's latest BGEN / BGENI
    long solo_seq = 0, slot_seq[MAX_SLOTS] = {};
    std::atomic<long> stop_upto{0}, solo_yield_upto{0}, bstop_upto[MAX_SLOTS], yield_upto[MAX_SLOTS];
    std::atomic<int> solo_yield_slot{-1};
    // STOP for the running request, as Session::generate takes it: set by begin() and by a STOP while it runs
    std::atomic<bool> stop_now{false};
    Input() {
        for (int i = 0; i < MAX_SLOTS; ++i) {
            bstop_upto[i] = 0;
            yield_upto[i] = 0;
        }
    }
    void run(std::istream& is = std::cin) {
        std::string line;
        while (std::getline(is, line)) {
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (line == "STOP") {
                std::lock_guard<std::mutex> lk(mu);
                stop_upto = seq;
                if (running > 0 && running == seq) stop_now = true;
                continue;
            }
            int slot = -1;
            if (std::sscanf(line.c_str(), "BSTOP %d", &slot) == 1) {
                if (slot >= 0 && slot < MAX_SLOTS) bstop_upto[slot] = slot_seq[slot];
                else std::fprintf(stderr, "sfnx: '%s': no slot %d (0..%d): nothing stopped\n", line.c_str(), slot, MAX_SLOTS - 1);
                continue;
            }
            if (std::sscanf(line.c_str(), "BYIELD %d", &slot) == 1) {
                if (slot >= 0 && slot < MAX_SLOTS) {
                    yield_upto[slot] = slot_seq[slot];
                    solo_yield_slot = slot;   // before the number: whoever sees the number sees this slot or a later one
                    solo_yield_upto = solo_seq;
                } else {
                    std::fprintf(stderr, "sfnx: '%s': no slot %d (0..%d): nothing yields\n", line.c_str(), slot, MAX_SLOTS - 1);
                }
                continue;
            }
            const std::string cmd = line.substr(0, line.find(' '));
            const bool request = cmd == "GEN" || cmd == "GENI" || cmd == "BGEN" || cmd == "BGENI";
            std::lock_guard<std::mutex> lk(mu);
            long n = 0;
            if (request) {
                n = ++seq;
                if (cmd == "GEN" || cmd == "GENI") solo_seq = n;
                else if (std::sscanf(line.c_str() + cmd.size(), " %d", &slot) == 1 && slot >= 0 && slot < MAX_SLOTS)
                    slot_seq[slot] = n;
            }
            lines.emplace_back(line, n);
            cv.notify_one();
        }
        std::lock_guard<std::mutex> lk(mu);
        eof = true;
        cv.notify_one();
    }
    // the next queued line and its request number (0: not a request): waiting for one (at most `most`) when wait, else
    // only if one is there
    bool next(std::string& line, long& n, bool wait, std::chrono::milliseconds most = std::chrono::milliseconds::max()) {
        std::unique_lock<std::mutex> lk(mu);
        if (wait && most == std::chrono::milliseconds::max()) cv.wait(lk, [&] { return !lines.empty() || eof; });
        else if (wait) cv.wait_for(lk, most, [&] { return !lines.empty() || eof; });
        if (lines.empty()) return false;
        line = std::move(lines.front().first);
        n = lines.front().second;
        lines.pop_front();
        return true;
    }
    bool closed() {
        std::lock_guard<std::mutex> lk(mu);
        return eof && lines.empty();
    }
    // the engine starts on request n / is done with it (stop_now follows STOP for it in between)
    void begin(long n) {
        std::lock_guard<std::mutex> lk(mu);
        running = n;
        stop_now = stop_upto == n;
    }
    void end() {
        std::lock_guard<std::mutex> lk(mu);
        running = 0;
        stop_now = false;
    }
    bool bstopped(int slot, long n) const { return bstop_upto[slot] >= n; }
    bool yielded(int slot, long n) const { return yield_upto[slot] >= n; }
    // the slot a BYIELD named for solo request n, -1: none came for it
    int solo_yield(long n) const { return solo_yield_upto >= n ? solo_yield_slot.load() : -1; }
};

// begin() for a request, end() however its handling returns
struct Running {
    Input& in;
    Running(Input& i, long n) : in(i) { in.begin(n); }
    ~Running() { in.end(); }
};

}  // namespace sfnx

--- src/split/tools/sfnx_input_test.cpp
// sfnx_input_test: sfnx's stdin handling (sfnx_input.hpp) on scripted input, no GPU: which request each STOP, BSTOP
// and BYIELD acts on, whatever order the lines come in and however long a request waits in the queue.
//
//   bin/sfnx_input_test
#include "sfnx_input.hpp"

#include <cstdio>
#include <sstream>
#include <string>
#include <vector>

namespace {

int failures = 0;

void expect(bool ok, const char* what) {
    std::printf("%-72s %s\n", what, ok ? "ok" : "FAIL");
    if (!ok) ++failures;
}

// the queued lines of `script` (all of it read first: the engine had not reached any of them), with their numbers
struct Fed {
    sfnx::Input in;
    std::vector<std::pair<std::string, long>> q;
    explicit Fed(const std::string& script) {
        std::istringstream is(script);
        in.run(is);
        std::string line;
        long n = 0;
        while (in.next(line, n, false)) q.emplace_back(line, n);
    }
};

}  // namespace

int main() {
    {
        Fed f("GEN 5 1,2\nBGEN 1 5 3\nQUIT\n");
        expect(f.q.size() == 3 && f.q[0].second == 1 && f.q[1].second == 2 && f.q[2].second == 0,
               "requests numbered in arrival order, other lines 0");
        expect(f.in.closed(), "closed at the end of input with the queue drained");
    }
    {
        Fed f("STOP\nGEN 5 1,2\n");
        f.in.begin(f.q[0].second);
        expect(!f.in.stop_now, "a STOP before a GEN's line does not stop it");
        f.in.end();
    }
    {
        Fed f("GEN 5 1,2\nSTOP\n");
        f.in.begin(f.q[0].second);
        expect(f.in.stop_now, "a STOP after a GEN's line stops it, though the engine reaches it later");
        f.in.end();
        expect(!f.in.stop_now, "stop_now is down between requests");
    }
    {
        // the case that clearing on arrival got wrong: A runs, STOP is meant for it, and B's line comes in before the
        // engine looks at the flag
        Fed f("GEN 5 1\n");
        f.in.begin(f.q[0].second);
        std::istringstream more("STOP\nGEN 5 2\n");
        f.in.run(more);
        expect(f.in.stop_now, "a STOP for the running request survives the next request's line");
        f.in.end();
        std::string line;
        long n = 0;
        f.in.next(line, n, false);
        f.in.begin(n);
        expect(!f.in.stop_now, "... and the request whose line came after it is not stopped");
        f.in.end();
    }
    {
        // a STOP after two queued lines: for the latest only (the front end sends a request's line and its STOP under one
        // control lock; the older line is another client's request)
        Fed f("GEN 5 1\nGEN 5 2\nSTOP\n");
        f.in.begin(f.q[0].second);
        const bool first = f.in.stop_now;
        f.in.end();
        f.in.begin(f.q[1].second);
        expect(!first && f.in.stop_now, "a STOP after two queued requests' lines stops the latest and not the older one");
        f.in.end();
    }
    {
        // a STOP while an older request runs and a newer line is queued: for the newer one, not the running one
        Fed f("GEN 5 1\nGEN 5 2\n");
        f.in.begin(f.q[0].second);
        std::istringstream more("STOP\n");
        f.in.run(more);
        expect(!f.in.stop_now, "a STOP for the latest line does not stop an older running request");
        f.in.end();
        f.in.begin(f.q[1].second);
        expect(f.in.stop_now, "... and stops the latest when it begins");
        f.in.end();
    }
    {
        Fed f("BSTOP 2\nBYIELD 2\nBGEN 2 5 1\n");
        const long n = f.q[0].second;
        expect(!f.in.bstopped(2, n) && !f.in.yielded(2, n), "BSTOP / BYIELD before a slot's BGEN line do not act on it");
    }
    {
        Fed f("BGEN 2 5 1\nBGEN 3 5 1\nBSTOP 2\nBYIELD 3\n");
        const long a = f.q[0].second, b = f.q[1].second;
        expect(f.in.bstopped(2, a) && !f.in.bstopped(3, b), "BSTOP acts on its own slot's request only");
        expect(f.in.yielded(3, b) && !f.in.yielded(2, a), "BYIELD acts on its own slot's request only");
    }
    {
        Fed f("BGEN 2 5 1\nBSTOP 2\nBGEN 2 5 9\n");
        expect(f.in.bstopped(2, f.q[0].second) && !f.in.bstopped(2, f.q[1].second),
               "a slot's next BGEN is not stopped by the BSTOP for the one before");
    }
    {
        Fed f("GEN 5 1,2\nBYIELD 4\n");
        expect(f.in.solo_yield(f.q[0].second) == 4, "BYIELD after a GEN's line gives its read way into the slot named");
    }
    {
        Fed f("BYIELD 4\nGEN 5 1,2\n");
        expect(f.in.solo_yield(f.q[0].second) == -1, "a BYIELD before a GEN's line does not act on it");
    }
    {
        Fed f("GEN 5 1\nBYIELD 4\nGEN 5 2\n");
        expect(f.in.solo_yield(f.q[1].second) == -1, "a BYIELD for one GEN does not act on the next");
    }
    {
        Fed f("GEN 5 1\nBGEN 3 5 1\nBYIELD 3\n");
        // a BYIELD names a slot: for BGEN 3 it is that read's; the solo request before it is not on the control lines
        // then (the front end sends one request's control lines at a time), so its number is behind
        expect(f.in.yielded(3, f.q[1].second), "BYIELD for a BGEN's slot acts on that BGEN");
    }
    {
        Fed f("BSTOP 9\nBYIELD -1\nGEN 5 1\n");
        expect(f.q.size() == 1 && f.q[0].first == "GEN 5 1", "BSTOP / BYIELD outside the slots are dropped, not queued");
        expect(f.q[0].second == 1, "and take no request number");
    }
    {
        // "BSTOP x" has no slot number: it is no control line, so it is queued (the engine answers ERR for it)
        Fed f("BSTOP x\n");
        expect(f.q.size() == 1 && f.q[0].second == 0, "a malformed BSTOP is queued as a line, not a request");
    }
    {
        Fed f("GEN 5 1\r\nSTOP\r\n");
        f.in.begin(f.q[0].second);
        expect(f.q[0].first == "GEN 5 1" && f.in.stop_now, "CRLF line ends");
        f.in.end();
    }
    std::printf(failures ? "sfnx_input_test: %d FAILED\n" : "sfnx_input_test: all ok\n", failures);
    return failures ? 1 : 0;
}

